    hermit: { n: 'Hermit', slot: 'hut', sells: ['herbs', 'apple'], keys: 1, stock: ['s7'], say: ['"I came out here to be alone. That hasn’t worked. Sit down."', '"People walk three days to ask me things. I sell herbs and the odd hint key."'] },
    herbalist: { n: 'Herbalist', slot: 'cottage2', sells: ['herbs', 'honey'], tonic: 1, stock: ['s2'], say: ['"I finished the fresh draughts this morning. I’ll show you the herbs too if you’d rather pack those."', '"Say if you fell on the way here. I can sell you something to help with the hurt before you go on."'] },
    beekeeper: { n: 'Beekeeper', slot: 'cottage2', sells: ['honey', 'cider'], stock: [], say: ['"Walk slowly and the bees won’t mind you."', '"I’ve got honey in the jar and cider in the jug. You can buy either."'] },
    woodcutter: { n: 'Woodcutter', slot: 'cabin', sells: ['apple', 'cider'], mats: 1, stock: ['s8'], say: ['"Mind the axe by the door. My daughter put out apples and cider for people coming off the road."', '"I’ve got room by the stump if you want to sit. The things I’ve got for sale are in the shed."'] },
    miner: { n: 'Miner', slot: 'mine', sells: ['loaf'], mats: 1, gear: 1, stock: ['s8'], say: ['"I get a little ore out of this hill every day. Would you like to buy some?"', '"The dark doesn’t bother me. Sunlight takes some getting used to."'] },
    tinker: { n: 'Tinker', roam: 1, sells: ['apple'], keys: 1, gear: 2, say: ['"I traded for some gear at my last stop. I’ve got room to put it down here if you want a look."', '"Have a look in my pack. I’ve got an apple left too."'] },
    minstrel: { n: 'Minstrel', roam: 1, sells: [], song: 1, say: ['"I’m resting my feet a while. Would you like to hear a song?"', '"I’ve been playing for the crews along this road. They still ask for the songs they knew as children."'] },
